def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find the full row or column of color 2.
    line = None
    axis = None
    for r in range(h):
        if all(grid[r][c] == 2 for c in range(w)):
            line, axis = r, 0
            break
    if line is None:
        for c in range(w):
            if all(grid[r][c] == 2 for r in range(h)):
                line, axis = c, 1
                break
    if line is None:
        return out

    # The background is the most common color; the remaining non-line color
    # forms the object.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    pts = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] != bg and grid[r][c] != 2]
    if not pts:
        return out

    coords = [r if axis == 0 else c for r, c in pts]
    lo, hi = min(coords), max(coords)
    length = h if axis == 0 else w

    # Move the object toward the 2-line until it is adjacent to it.
    if hi < line:
        shift = line - 1 - hi
        far_edge = lo + shift
        marker = far_edge - 1
    elif lo > line:
        shift = line + 1 - lo
        far_edge = hi + shift
        marker = far_edge + 1
    else:
        return out

    moved = []
    for r, c in pts:
        if axis == 0:
            moved.append((r + shift, c))
        else:
            moved.append((r, c + shift))

    # Clear the original object, then place it in its new position.
    for r, c in pts:
        out[r][c] = bg
    for r, c in moved:
        out[r][c] = grid[pts[0][0]][pts[0][1]] if False else grid[r - shift][c] if axis == 0 else grid[r][c - shift]

    # Draw the 8 marker line on the side away from the 2-line.
    if 0 <= marker < length:
        if axis == 0:
            out[marker] = [8] * w
        else:
            for r in range(h):
                out[r][marker] = 8

    return out
